import unreal, os, json
if '.blueprint-build' not in os.path.abspath(unreal.Paths.project_dir()).replace('\\','/').split('/'):
    raise RuntimeError('Fixture project required')
if any(name.endswith(('.umap','.uasset')) for _,_,names in os.walk(os.path.join(unreal.Paths.project_dir(),'Content')) for name in names):
    raise RuntimeError('Empty fixture Content required; existing assets will not be overwritten')
lib=unreal.EditorAssetLibrary
mesh=lib.duplicate_asset('/Engine/BasicShapes/Cube','/Game/SocketCube')
socket=unreal.StaticMeshSocket(outer=mesh)
socket.set_editor_property('socket_name','ProbeSocket')
socket.set_editor_property('relative_location',unreal.Vector(25,0,10))
socket.set_editor_property('relative_rotation',unreal.Rotator(yaw=90))
mesh.add_socket(socket)
lib.save_loaded_asset(mesh)
tools=unreal.AssetToolsHelpers.get_asset_tools()
factory=unreal.BlueprintFactory()
factory.set_editor_property('parent_class',unreal.Actor)
bp=tools.create_asset('BP_ComponentBase','/Game',unreal.Blueprint,factory)
subsystem=unreal.get_engine_subsystem(unreal.SubobjectDataSubsystem)
handles=subsystem.k2_gather_subobject_data_for_blueprint(bp)
handle,reason=subsystem.add_new_subobject(unreal.AddNewSubobjectParams(parent_handle=handles[0],new_class=unreal.StaticMeshComponent,blueprint_context=bp))
data=unreal.SubobjectDataBlueprintFunctionLibrary.get_data(handle)
component=unreal.SubobjectDataBlueprintFunctionLibrary.get_object(data)
subsystem.rename_subobject(handle,unreal.Text('InheritedMesh'))
component.set_editor_property('static_mesh',mesh)
component.set_editor_property('relative_location',unreal.Vector(40,0,0))
unreal.BlueprintEditorLibrary.compile_blueprint(bp)
lib.save_loaded_asset(bp)
factory=unreal.BlueprintFactory()
factory.set_editor_property('parent_class',bp.generated_class())
childbp=tools.create_asset('BP_ComponentChild','/Game',unreal.Blueprint,factory)
unreal.BlueprintEditorLibrary.compile_blueprint(childbp)
lib.save_loaded_asset(childbp)
levels=unreal.get_editor_subsystem(unreal.LevelEditorSubsystem)
actors=unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
levels.new_level('/Game/SocketMap')
parent=actors.spawn_actor_from_class(unreal.StaticMeshActor,unreal.Vector(100,200,30))
parent.set_actor_label('Socket Parent');parent.static_mesh_component.set_static_mesh(mesh)
parent.set_actor_rotation(unreal.Rotator(yaw=90),False);parent.set_actor_scale3d(unreal.Vector(2,2,2))
child=actors.spawn_actor_from_class(unreal.StaticMeshActor,unreal.Vector(0,0,0))
child.set_actor_label('Socket Child');child.static_mesh_component.set_static_mesh(unreal.load_asset('/Engine/BasicShapes/Sphere'))
child.attach_to_component(parent.static_mesh_component,'ProbeSocket',unreal.AttachmentRule.KEEP_RELATIVE,unreal.AttachmentRule.KEEP_RELATIVE,unreal.AttachmentRule.KEEP_RELATIVE,False)
child.set_actor_relative_location(unreal.Vector(5,0,0),False,False)
inherited=actors.spawn_actor_from_class(childbp.generated_class(),unreal.Vector(400,100,0))
inherited.set_actor_label('Inherited Component Parent')
inherited.set_actor_rotation(unreal.Rotator(yaw=90),False)
component=inherited.get_components_by_class(unreal.StaticMeshComponent)[0]
grandchild=actors.spawn_actor_from_class(unreal.StaticMeshActor,unreal.Vector(0,0,0))
grandchild.set_actor_label('Inherited Socket Child');grandchild.static_mesh_component.set_static_mesh(unreal.load_asset('/Engine/BasicShapes/Sphere'))
grandchild.static_mesh_component.set_mobility(unreal.ComponentMobility.MOVABLE)
if not grandchild.attach_to_component(component,'ProbeSocket',unreal.AttachmentRule.KEEP_RELATIVE,unreal.AttachmentRule.KEEP_RELATIVE,unreal.AttachmentRule.KEEP_RELATIVE,False): raise RuntimeError('Inherited socket attachment failed')
grandchild.set_actor_relative_location(unreal.Vector(5,0,0),False,False)
world=unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem).get_editor_world()
unreal.EditorLoadingAndSavingUtils.save_map(world,'/Game/SocketMap')
positions={}
for actor in (parent,child,inherited,grandchild):
    p=actor.get_actor_location();positions[actor.get_actor_label()]=[p.x,p.y,p.z]
p=component.get_world_location()
positions['Inherited Mesh']=[p.x,p.y,p.z]
with open(os.path.join(unreal.Paths.project_dir(),'socket-reference.json'),'w') as file:json.dump(positions,file)

